// === NORMALIZE + HASH (EMQ) — SHA-256 thuần JS, KHÔNG require('crypto') (chạy ở mọi n8n, kể cả task-runner chặn builtin) ===
function sha256(input){ if(input===undefined||input===null||input==='')return undefined; var ascii=unescape(encodeURIComponent(String(input).trim().toLowerCase())); function rr(v,a){return (v>>>a)|(v<<(32-a));} var mp=Math.pow,mw=mp(2,32),res='',words=[],bl=ascii.length*8; var hash=sha256.h=sha256.h||[],k=sha256.k=sha256.k||[],pc=k.length,iC={}; for(var cand=2;pc<64;cand++){ if(!iC[cand]){ for(var i=0;i<313;i+=cand){iC[i]=cand;} hash[pc]=(mp(cand,.5)*mw)|0; k[pc++]=(mp(cand,1/3)*mw)|0; } } ascii+=String.fromCharCode(128); while(ascii.length%64-56)ascii+=String.fromCharCode(0); for(i=0;i<ascii.length;i++){ var j=ascii.charCodeAt(i); words[i>>2]|=j<<((3-i)%4)*8; } words[words.length]=((bl/mw)|0); words[words.length]=bl; for(j=0;j<words.length;){ var w=words.slice(j,j+=16),oh=hash; hash=hash.slice(0,8); for(i=0;i<64;i++){ var w15=w[i-15],w2=w[i-2],a=hash[0],e=hash[4]; var t1=hash[7]+(rr(e,6)^rr(e,11)^rr(e,25))+((e&hash[5])^((~e)&hash[6]))+k[i]+(w[i]=(i<16)?w[i]:(w[i-16]+(rr(w15,7)^rr(w15,18)^(w15>>>3))+w[i-7]+(rr(w2,17)^rr(w2,19)^(w2>>>10)))|0); var t2=(rr(a,2)^rr(a,13)^rr(a,22))+((a&hash[1])^(a&hash[2])^(hash[1]&hash[2])); hash=[(t1+t2)|0].concat(hash); hash[4]=(hash[4]+t1)|0; } for(i=0;i<8;i++){hash[i]=(hash[i]+oh[i])|0;} } for(i=0;i<8;i++){ for(j=3;j+1;j--){ var b=(hash[i]>>(j*8))&255; res+=((b<16)?0:'')+b.toString(16); } } return res; }
const clean = (o) => Object.fromEntries(Object.entries(o).filter(([,v]) => v !== undefined && v !== '' && !(Array.isArray(v) && v.length === 0)));

const item = $input.first().json;
let bodyRaw = item.body;
if (typeof bodyRaw === 'string') { try { bodyRaw = JSON.parse(bodyRaw); } catch (e) { bodyRaw = {}; } }
const b = (bodyRaw && typeof bodyRaw === 'object' && Object.keys(bodyRaw).length) ? bodyRaw : item;
const h = item.headers || {};

const event_name = b.event_name || 'Lead';
const event_id = b.event_id || (b.order_id ? String(b.order_id) : ('evt_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8)));

const user_data = clean({
  em: b.email ? [sha256(b.email)] : undefined,
  ph: b.phone ? [sha256(String(b.phone).replace(/[^0-9]/g, ''))] : undefined,
  external_id: b.user_id ? [sha256(b.user_id)] : undefined,
  fbp: b.fbp || undefined,
  fbc: b.fbc || undefined,
  client_ip_address: (h['x-forwarded-for'] ? String(h['x-forwarded-for']).split(',')[0].trim() : (h['x-real-ip'] || undefined)),
  client_user_agent: h['user-agent'] || undefined
});

const custom_data = clean({
  currency: b.currency || undefined,
  value: (b.value !== undefined && b.value !== null) ? Number(b.value) : undefined,
  content_ids: b.content_ids || (b.plan ? [b.plan] : undefined),
  content_type: b.content_type || (b.plan ? 'product' : undefined)
});

const out = {
  event_name,
  event_id,
  event_time: Math.floor(Date.now() / 1000),
  event_source_url: b.event_source_url || b.url || b.landing_page_url || '',
  site: b.site || 'cinbase-landing',
  email: b.email || '',
  name: b.name || '',
  phone: b.phone || '',
  user_data,
  custom_data,
  utm_source: b.utm_source || b.source || '',
  utm_medium: b.utm_medium || b.adset || '',
  utm_campaign: b.utm_campaign || b.campaign || '',
  utm_content: b.utm_content || b.ad || '',
  utm_term: b.utm_term || b.term || '',
  industry: b.industry || '',
  goal: b.goal || '',
  vat_invoice: b.vat_invoice || ''
};
return [{ json: out }];

// === BUILD META CAPI PAYLOAD ===
const d = $input.first().json;
const clean = (o) => Object.fromEntries(Object.entries(o || {}).filter(([,v]) => v !== undefined && v !== '' && !(Array.isArray(v) && v.length === 0)));
const payload = {
  data: [
    clean({
      event_name: d.event_name,
      event_time: d.event_time,
      event_id: d.event_id,
      action_source: 'website',
      event_source_url: d.event_source_url,
      user_data: clean(d.user_data),
      custom_data: clean(d.custom_data)
    })
  ]
  // test_event_code: 'TESTxxxxx'  // bo comment khi test trong Events Manager
};
return [{ json: { ...d, capi: payload } }];
